WITH filtered_store_sales AS (SELECT *, ROUND(units * 100, 2) AS units_scaled FROM store_sales WHERE units < 35), product_id_summary AS (SELECT product_id, MIN(sale_date) AS min_sale_date, SUM(units_scaled) AS total_units_scaled FROM filtered_store_sales GROUP BY product_id) SELECT product_id, min_sale_date, total_units_scaled FROM product_id_summary WHERE total_units_scaled > 300 ORDER BY product_id
